  TextOutFlags: Integer;
  DefaultDraw: Boolean;

begin
  // PI compatibility extension: preserve the original per-cell paint callback.
  DefaultDraw := True;
  if Assigned(FOnPiPaintCell) then
    FOnPiPaintCell(Self, PaintInfo, DefaultDraw);
  if not DefaultDraw then Exit;
  // Set a new OnChange event for the canvas' font so we know if the application changes it in the callbacks.

  property OnDrawText: TVTDrawTextEvent read FOnDrawText write FOnDrawText;
public
